REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('2959','111527','Localized or diffuse reduction in blood flow through the vertebrobasilar arterial system, which supplies the BRAIN STEM; CEREBELLUM; OCCIPITAL LOBE; medial TEMPORAL LOBE; and THALAMUS. Characteristic clinical features include SYNCOPE; lightheadedness; visual disturbances; and VERTIGO. BRAIN STEM INFARCTIONS or other BRAIN INFARCTION may be associated.','en','1','2007-10-18 04:28:24','1',NULL,'2959FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('2960','111528','Localized or diffuse reduction in blood flow through the vertebrobasilar arterial system, which supplies the BRAIN STEM; CEREBELLUM; OCCIPITAL LOBE; medial TEMPORAL LOBE; and THALAMUS. Characteristic clinical features include SYNCOPE; lightheadedness; visual disturbances; and VERTIGO. BRAIN STEM INFARCTIONS or other BRAIN INFARCTION may be associated.','en','1','2007-10-18 04:28:24','1',NULL,'2960FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
