REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('3320','112397','Inflammation of a vein associated with thrombus formation.','en','1','2007-10-18 04:28:24','1',NULL,'3320FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
