REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('3505','113008','Disorders in which the essential feature is a severe disturbance in mood (depression, anxiety, elation, and excitement) accompanied by psychotic symptoms such as delusions, hallucinations, gross impairment in reality testing, etc.','en','1','2007-10-18 04:28:24','1',NULL,'3505FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
