REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('3782','113696','Tumors or cancer of the either the COLON or RECTUM or both. The most frequent malignant tumor in the United States. Etiological factors which increase the risk of colorectal cancer include chronic ulcerative colitis, familial polyposis of the colon, exposure to asbestos, irradiation of the cervix.','en','1','2007-10-18 04:28:24','1',NULL,'3782FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
