REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4106','114816','Fractures of the skull which may result from penetrating or nonpenetrating head injuries or rarely BONE DISEASES (see also FRACTURES, SPONTANEOUS). Skull fractures may be classified by location (e.g., SKULL FRACTURE, BASILAR), radiographic appearance (e.g., linear), or based upon cranial integrity (e.g., SKULL FRACTURE, DEPRESSED).','en','1','2007-10-18 04:28:24','1',NULL,'4106FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
