REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4296','115368','A transient unconjugated hyperbilirubinemia that occurs between the second and fifth days of life because the hepatic enzyme GLUCURONOSYLTRANSFERASE required for BILIRUBIN detoxification is inadquedate.','en','1','2007-10-18 04:28:24','1','2016-09-16 01:58:28','4296FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
