REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4631','116110','The inability of a kidney to excrete metabolites at normal plasma levels under conditions of normal loading, or the inability to retain electrolytes under conditions of normal intake. In the acute form (KIDNEY FAILURE, ACUTE), it is marked by uremia and usually by oliguria or anuria, with hyperkalemia and pulmonary edema. The chronic form (KIDNEY FAILURE, CHRONIC) is irreversible and requires hemodialysis.','en','1','2007-10-18 04:28:24','1',NULL,'4631FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
