REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4643','116149','A disease of the inner ear characterized by vertigo, tinnitus, and fluctuating hearing loss often accompanied by fullness in the affected ear. ENDOLYMPHATIC HYDROPS (swelling of the endolymph-containing structures) is the main pathologic finding.','en','1','2007-10-18 04:28:24','1',NULL,'4643FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
