REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4812','116631','A personality disorder manifested by a profound defect in the ability to form social relationships, no desire for social involvement, and an indifference to praise or criticism.','en','1','2007-10-18 04:28:24','1',NULL,'4812FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
