REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4821','116641','A disorder present in the newborn infant in which constriction rings or bands, causing soft tissue depressions, encircle digits, extremities, or limbs and sometimes the neck, thorax, or abdomen. They may be associated with intrauterine amputations.','en','1','2007-10-18 04:28:24','1',NULL,'4821FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
