REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4825','116673','Bleeding within the cranial vault induced by penetrating and nonpenetrating traumatic injuries, including hemorrhages into the epidural, subdural and subarachnoid spaces, cerebral hemispheres, DIENCEPHALON; BRAIN STEM; and CEREBELLUM.','en','1','2007-10-18 04:28:24','1',NULL,'4825FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4827','116675','Bleeding within the intracranial cavity, including hemorrhages in the brain and within the cranial epidural, subdural, and subarachnoid spaces.','en','1','2007-10-18 04:28:24','1',NULL,'4827FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4828','116677','Bleeding into a cerebral hemisphere of the brain, including lobar, subcortical white matter, and basal ganglia hemorrhages. Commonly associated conditions include HYPERTENSION; INTRACRANIAL ARTERIOSCLEROSIS; INTRACRANIAL ANEURYSM; CRANIOCEREBRAL TRAUMA; INTRACRANIAL ARTERIOVENOUS MALFORMATIONS; CEREBRAL AMYLOID ANGIOPATHY; and CEREBRAL INFARCTION.','en','1','2007-10-18 04:28:24','1','2015-11-04 03:56:00','4828FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4829','116689','Any impairment, arrest, or reversal of the normal flow of intestinal contents toward the anus.','en','1','2007-10-18 04:28:24','1',NULL,'4829FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
