REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('4873','116874','Dysfunction of one or more cranial nerves causally related to a traumatic injury. Penetrating and nonpenetrating CRANIOCEREBRAL TRAUMA; NECK INJURIES; and trauma to the facial region are conditions associated with cranial nerve injuries.','en','1','2007-10-18 04:28:24','1',NULL,'4873FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
