REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5018','117419','A form of nonthrombocytopenic purpura due to a hypersensitivity vasculitis associated with a variety of clinical symptoms including urticaria and erythema, arthropathy and arthritis, gastrointestinal symptoms, and renal involvement.','en','1','2007-10-18 04:28:24','1',NULL,'5018FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
