REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5025','117431','Abnormally increased activity of the parathyroid glands, which may be primary or secondary (HYPERPARATHYRODISM, SECONDARY). Primary hyperparathyroidism is associated with neoplasia or hyperplasia. The excess of parathyroid hormone leads to alteration in function of bone, renal tubules, and gastrointestinal mucosa. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'5025FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
