REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5028','117437','A rare familial condition characterized by massive chylomicronemia and decreased levels of other lipoproteins. It is due to deficiency of lipoprotein lipase, an alkaline triglyceride hydrolase which catalyzes an important step in the extrahepatic removal of triglyceride-rich lipoproteins from the blood.','en','1','2007-10-18 04:28:24','1',NULL,'5028FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
