REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5059','117503','A personality disorder characterized by overly reactive and intensely expressed or overly dramatic behavior, proneness to exaggeration, emotional excitability, and disturbances in interpersonal relationships.','en','1','2007-10-18 04:28:24','1',NULL,'5059FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5060','117513','Infecton resulting from inhalation or ingestion of spores of the fungus of the genus HISTOPLASMA, species H. capsulatum. It is worldwide in distribution and particularly common in the midwestern United States. (From Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1','2011-12-22 15:56:06','5060FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
