REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5238','117911','A nodular, tumorlike lesion in or about a tendon sheath or joint capsule, especially of the hands, wrists, or feet. It is not a true cyst as it lacks an epithelial wall, and it does not communicate with the underlying synovial space. The lesion represents a focal accumulation of mucin in the dermis of the dorsal aspect of the distal phalanges or, less often, other portions of the extremities.','en','1','2007-10-18 04:28:24','1',NULL,'5238FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5239','117913','A nodular, tumorlike lesion in or about a tendon sheath or joint capsule, especially of the hands, wrists, or feet. It is not a true cyst as it lacks an epithelial wall, and it does not communicate with the underlying synovial space. The lesion represents a focal accumulation of mucin in the dermis of the dorsal aspect of the distal phalanges or, less often, other portions of the extremities.','en','1','2007-10-18 04:28:24','1',NULL,'5239FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
