REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5589','119072','A gland in males that surrounds the neck of the BLADDER and the URETHRA. It secretes a substance that liquifies coagulated semen. It is situated in the pelvic cavity behind the lower part of the PUBIC SYMPHYSIS, above the deep layer of the triangular ligament, and rests upon the RECTUM.','en','1','2007-10-18 04:28:24','1',NULL,'5589FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
