REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5720','119457','Diabetes characterized by the ability to survive without ketoacidosis in the absence of insulin therapy. It is usually of slow onset and patients exhibit a tendency to obesity.','en','1','2007-10-18 04:28:24','1',NULL,'5720FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
