REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('5961','120299','Heterogeneous group of immunodeficiency syndromes characterized by hypogammaglobulinemia of most isotypes, variable B-cell defects, and the presence of recurrent bacterial infections.','en','1','2007-10-18 04:28:24','1',NULL,'5961FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
