REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6089','120549','Inflammatory disease of unknown cause which involves the mucosa of the colon. Onset may be acute and fulminant, and its course often continues chronically in an intermittent or continuous form. Diarrhea is a common symptom and bleeding an almost constant concomitant symptom.','en','1','2007-10-18 04:28:24','1',NULL,'6089FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6090','120556','Ulceration of the skin and underlying structures of the lower extremity. About 90% of the cases are due to venous insufficiency (VARICOSE ULCER), 5% to arterial disease, and the remaining 5% to other causes.','en','1','2007-10-18 04:28:24','1',NULL,'6090FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
