REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6141','120729','A genus of gram-negative bacteria whose species cause a variety of diseases in humans, other mammals, and birds.','en','1','2007-10-18 04:28:24','1','2013-05-05 23:12:02','6141FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
