REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6215','120958','An abnormal concretion occurring mostly in the urinary and biliary tracts, usually composed of mineral salts. Also called stones.','en','1','2007-10-18 04:28:24','1',NULL,'6215FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
