REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6248','121059','Subnormal intellectual functioning which originates during the developmental period. This has multiple potential etiologies, including genetic defects and perinatal insults. Intelligence quotient (IQ) scores are commonly used to determine whether an individual is mentally retarded. IQ scores between 70 and 79 are in the borderline mentally retarded range. Scores below 67 are in the retarded range. (Joynt, Clinical Neurology, 1992, Ch55, p28)','en','1','2007-10-18 04:28:24','1',NULL,'6248FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6249','121060','A condition in which the intraocular pressure is elevated above normal and which may lead to glaucoma.','en','1','2007-10-18 04:28:24','1','2012-10-21 18:13:06','6249FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
