REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6251','121064','Benign unilocular lytic areas in the proximal end of a long bone with well defined and narrow endosteal margins. The cysts contain fluid and the cyst walls may contain some giant cells. Bone cysts usually occur in males between the ages 3-15 years.','en','1','2007-10-18 04:28:24','1',NULL,'6251FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6253','121087','Spontaneous or near spontaneous bleeding caused by a defect in clotting mechanisms (BLOOD COAGULATION DISORDERS) or another abnormality causing a structural flaw in the blood vessels (VASCULAR HEMOSTATIC DISORDERS).','en','1','2007-10-18 04:28:24','1','2013-05-06 21:03:39','6253FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6254','121089','Hemorrhagic and thrombotic disorders that occur as a consequence of abnormalities in blood coagulation due to a variety of factors sych as COAGULATION PROTEIN DISORDERS, BLOOD PLATELET DISORDERS, BLOOD PROTEIN DISORDERS or nutritional conditions.','en','1','2007-10-18 04:28:24','1','2013-05-06 21:00:22','6254FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
