REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6269','121147','Paralysis of one or both vocal cords, which produces hoarseness or aphonia. This condition may be caused by diseases of the medulla (e.g., LATERAL MEDULLARY SYNDROME), VAGUS NERVE, or recurrent laryngeal nerve. Neuromuscular junction diseases and local myopathic processes may also affect vocal cord function. (Adams et al., Principles of Neurology, 6th ed, p1380)','en','1','2007-10-18 04:28:24','1',NULL,'6269FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6270','121152','A general term for the complete or partial loss of the ability to hear from one or both ears. Deafness may result from EAR DISEASES; VESTIBULOCOCHLEAR NERVE DISEASES; or BRAIN DISEASES.','en','1','2007-10-18 04:28:24','1','2012-07-15 22:03:26','6270FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
