REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6529','121832','An inflammatory process of the mucous membranes of the paranasal sinuses that occurs in three stages: acute, subacute, and chronic. Sinusitis results from any condition causing ostial obstruction or from pathophysiologic changes in the mucociliary transport mechanism.','en','1','2007-10-18 04:28:24','1',NULL,'6529FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
