REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6590','121988','Inflammation of the maxillary sinus. In most cases it is the result of infection by the bacteria HAEMOPHILUS INFLUENZAE, STREPTOCOCCUS PNEUMONIAE, and STAPHYLOCOCCUS AUREUS. This condition may be acute or chronic.','en','1','2007-10-18 04:28:24','1',NULL,'6590FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
