REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('6629','122076','Exudative and proliferative inflammatory alterations of the endocardium, characterized by the presence of vegetations on the surface of the endocardium or in the endocardium itself, and most commonly involving a heart valve, but sometimes affecting the inner lining of the cardiac chambers or the endocardium elsewhere. It may occur as a primary disorder or as a complication of or in association with another disease. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'6629FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
