REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7226','124054','Gastric and/or enteric tuberculosis. This condition is marked by spreading ulcers and diarrhea.','en','1','2007-10-18 04:28:24','1',NULL,'7226FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
