REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7402','124638','A general term describing various dermatophytoses. Specific types include TINEA CAPITIS (ringworm of the scalp), TINEA FAVOSA (of scalp and skin), TINEA PEDIS (athlete\'s foot), and tinea unguium (see ONYCHOMYCOSIS, ringworm of the nails). (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'7402FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7403','124639','A general term describing various dermatophytoses. Specific types include TINEA CAPITIS (ringworm of the scalp), TINEA FAVOSA (of scalp and skin), TINEA PEDIS (athlete\'s foot), and tinea unguium (see ONYCHOMYCOSIS, ringworm of the nails). (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'7403FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7404','124640','A general term describing various dermatophytoses. Specific types include TINEA CAPITIS (ringworm of the scalp), TINEA FAVOSA (of scalp and skin), TINEA PEDIS (athlete\'s foot), and tinea unguium (see ONYCHOMYCOSIS, ringworm of the nails). (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1','2015-04-06 13:55:31','7404FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7405','124642','The collective name for the islands of the central Pacific Ocean, including the Austral Islands, Cook Islands, Easter Island, HAWAII, NEW ZEALAND, Phoenix Islands, PITCAIRN ISLAND, SAMOA, TONGA, Tuamotu Archipelago, Wake Island, and Wallis and Futuna Islands. Polynesians are of the Caucasoid race, but many are of mixed origin. Polynesia is from the Greek poly, many + nesos, island, with reference to the many islands in the group. (From Webster\'s New Geographical Dictionary, 1988, p966 & Room, Brewer\'s Dictionary of Names, 1992, p426)','en','1','2007-10-18 04:28:24','1',NULL,'7405FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7406','124644','A general term describing various dermatophytoses. Specific types include TINEA CAPITIS (ringworm of the scalp), TINEA FAVOSA (of scalp and skin), TINEA PEDIS (athlete\'s foot), and tinea unguium (see ONYCHOMYCOSIS, ringworm of the nails). (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'7406FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
