REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7719','125884','Neoplasms of whatever cell type or origin, occurring in the extraskeletal connective tissue framework of the body including the organs of locomotion and their various component structures, such as nerves, blood vessels, lymphatics, etc.','en','1','2007-10-18 04:28:24','1',NULL,'7719FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7720','125886','A variant of bullous erythema multiforme. It ranges from mild skin and mucous membrane lesions to a severe, sometimes fatal systemic disorder. Ocular symptoms include ulcerative conjunctivitis, keratitis, iritis, uveitis, and sometimes blindness. The cause of the disease is unknown.','en','1','2007-10-18 04:28:24','1','2015-04-06 15:29:36','7720FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7721','125889','Acquired, familial, and congenital disorders of skeletal muscle (MUSCLE, SKELETAL) and smooth muscle (MUSCLE, SMOOTH).','en','1','2007-10-18 04:28:24','1',NULL,'7721FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
