REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7920','126570','Repeated physical injuries inflicted on the child by the parent, parents, or surrogate parent; often triggered by the child\'s minor and normal irritating behavior.','en','1','2007-10-18 04:28:24','1',NULL,'7920FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7921','126573','A form of cutaneous T-cell lymphoma manifested by generalized exfoliative erythroderma, intense pruritus, peripheral lymphadenopathy, and abnormal hyperchromatic mononuclear cells in the skin, lymph nodes, and peripheral blood (Sezary cells). (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'7921FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7922','126574','A condition in which there is a derivation of pleasure from inflicting pain, discomfort or humiliation on another person or persons. The sexual significance of sadistic wishes or behavior may be conscious or unconscious.','en','1','2007-10-18 04:28:24','1',NULL,'7922FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
