REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7952','126633','Group of rare congenital disorders characterized by impairment of both humoral and cell-mediated immunity, leukopenia, and low or absent antibody levels. It is inherited as an X-linked or autosomal recessive defect. About half of the patients with autosomal recessive SCID are deficient in the enzyme adenosine deaminase.','en','1','2007-10-18 04:28:24','1',NULL,'7952FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('7953','126634','Inflammatory disease of unknown cause which involves the mucosa of the colon. Onset may be acute and fulminant, and its course often continues chronically in an intermittent or continuous form. Diarrhea is a common symptom and bleeding an almost constant concomitant symptom.','en','1','2007-10-18 04:28:24','1',NULL,'7953FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
