REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('8086','126968','Diminution or cessation of secretion of one or more hormones from the anterior pituitary gland (including LH; FSH; SOMATOTROPIN; and CORTICOTROPIN). This may result from surgical or radiation ablation, non-secretory PITUITARY NEOPLASMS, metastatic tumors, infarction, PITUITARY APOPLEXY, infiltrative or granulomatous processes, and other conditions.','en','1','2007-10-18 04:28:24','1',NULL,'8086FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
