REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('8352','127683','Descriptive histopathologic term for renal disease without an inflammatory component.','en','1','2007-10-18 04:28:24','1',NULL,'8352FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('8354','127691','Hypertension due to renal diseases, especially chronic parenchymal disease. Hypertension as a result of compression or obstruction of the renal artery or its branches is HYPERTENSION, RENOVASCULAR.','en','1','2007-10-18 04:28:24','1',NULL,'8354FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
