REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('8364','127710','Narrowing or occlusion of the renal arteries. It is due usually to atherosclerosis, fibromuscular dysplasia, thrombosis, embolism, or external pressure. It may result in renovascular hypertension.','en','1','2007-10-18 04:28:24','1',NULL,'8364FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
