REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('9434','130984','Destructive lesions of the thoracic inlet with involvement of the brachial and sympathetic plexus or carcinoma of the lung apex. It is characterized by pain in the shoulder region radiating toward the axilla and scapula, sensory and motor disorders and wasting of the muscles of the hand, the Bernard-Horner syndrome, and compression of the blood vessels with edema. (Jablonski\'s Dictionary of Syndromes and Eponymic Diseases, 2d ed)','en','1','2007-10-18 04:28:24','1',NULL,'9434FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
