REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('9461','131093','Premature failure of ovulation associated with the permanent disappearance of oocytes and follicles from the ovary in women under the age of 40. If failure occurs while follicles are still present, the condition is called premature ovarian failure (OVARIAN FAILURE, PREMATURE).','en','1','2007-10-18 04:28:24','1',NULL,'9461FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('9462','131094','Any of several developmental anomalies involving the total or partial failure of the indifferent embryonic gonad to differentiate into ovary or testis. This concept includes gonadal agenesis.','en','1','2007-10-18 04:28:24','1',NULL,'9462FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('9464','131096','DEF: Malaria caused by infection with Plasmodium Ovale. DESC: Similar to P. Vivax, except untreated infection lasts less long. REF: Oxford Clinical Medicine','en','1','2007-10-18 04:28:24','1',NULL,'9464FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('9465','131109','A gelatinous membrane surmounting the acoustic maculae of the saccule and utricle and containing minute calciferous granules, known as otoconia, otoliths, or statoconia.','en','1','2007-10-18 04:28:24','1',NULL,'9465FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
