REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('9752','132597','Accumulation of purulent material in tissues, organs, or circumscribed spaces, usually associated with signs of infection.','en','1','2007-10-18 04:28:24','1',NULL,'9752FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
