REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('9973','133324','Tumors or cancer located in muscle tissue or specific muscles. They are differentiated from NEOPLASMS, MUSCLE TISSUE which are neoplasms composed of skeletal, cardiac, or smooth muscle tissue, such as MYOSARCOMA or LEIOMYOMA.','en','1','2007-10-18 04:28:24','1',NULL,'9973FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
