REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10002','133411','Acute conjunctival inflammation in the newborn, usually caused by maternal gonococcal infection. The causative agent is NEISSERIA GONORRHOEAE. The baby\'s eyes are contaminated during passage through the birth canal.','en','1','2007-10-18 04:28:24','1',NULL,'10002FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
