REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10289','134151','Pernicious vomiting of pregnancy. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'10289FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10290','134152','A familial congenital hemolytic anemia characterized by numerous abnormally shaped erythrocytes which are generally spheroidal. The erythrocytes have increased osmotic fragility and are abnormally permeable to sodium ions.','en','1','2007-10-18 04:28:24','1',NULL,'10290FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10291','134153','A familial congenital hemolytic anemia characterized by numerous abnormally shaped erythrocytes which are generally spheroidal. The erythrocytes have increased osmotic fragility and are abnormally permeable to sodium ions.','en','1','2007-10-18 04:28:24','1',NULL,'10291FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10292','134154','The classic hemophilia resulting from a deficiency of factor VIII. It is an inherited disorder of blood coagulation characterized by a permanent tendency to hemorrhage.','en','1','2007-10-18 04:28:24','1',NULL,'10292FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10293','134156','A major affective disorder marked by severe mood swings (manic or major depressive episodes) and a tendency to remission and recurrence.','en','1','2007-10-18 04:28:24','1',NULL,'10293FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10294','134157','Inflammatory disease of unknown cause which involves the mucosa of the colon. Onset may be acute and fulminant, and its course often continues chronically in an intermittent or continuous form. Diarrhea is a common symptom and bleeding an almost constant concomitant symptom.','en','1','2007-10-18 04:28:24','1',NULL,'10294FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
