REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10349','134292','An extra tooth, erupted or unerupted, resembling or unlike the other teeth in the group to which it belongs. Its presence may cause malposition of adjacent teeth or prevent their eruption.','en','1','2007-10-18 04:28:24','1','2013-07-10 13:52:42','10349FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
