REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10567','134882','A slowly growing malignant neoplasm derived from cartilage cells, occurring most frequently in pelvic bones or near the ends of long bones, in middle-aged and old people. Most chondrosarcomas arise de novo, but some may develop in a preexisting benign cartilaginous lesion or in patients with ENCHONDROMATOSIS. (Stedman, 25th ed)','en','1','2007-10-18 04:28:24','1',NULL,'10567FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
