REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10784','135316','Severe hypertension characterized by papilledema and necrosis of small arteries and arterioles. The diastolic pressure is generally greater than 130 mm Hg.','en','1','2007-10-18 04:28:24','1',NULL,'10784FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10785','135317','Heart decompensation in which the heart is unable to maintain adequate circulation of blood in the tissues of the body or to pump out the venous blood returned to it by the venous circulation.','en','1','2007-10-18 04:28:24','1',NULL,'10785FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
