REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10973','135850','Infections affecting those structures of the body which participate in the secretion and elimination of urine, i.e., the kidney, the ureters, the urinary bladder, and the urethra.','en','1','2007-10-18 04:28:24','1',NULL,'10973FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
