REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('10975','135854','A neoplastic disease of the lymphoreticular cells which is considered to be a rare type of chronic leukemia; it is characterized by an insidious onset, splenomegaly, anemia, granulocytopenia, thrombocytopenia, little or no lymphadenopathy, and the presence of \"hairy\" or \"flagellated\" cells in the blood and bone marrow.','en','1','2007-10-18 04:28:24','1',NULL,'10975FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
