REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11205','136552','Enlargement of the thyroid gland in a significantly large fraction of a population group, generally considered to be due to insufficient iodine in the diet.','en','1','2007-10-18 04:28:24','1',NULL,'11205FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11206','136555','A condition produced by dietary or metabolic deficiency. The term includes all diseases caused by an insufficient supply of essential nutrients, i.e., protein (or amino acids), vitamins, and minerals. It also includes an inadequacy of calories. (From Dorland, 27th ed; Stedman, 25th ed)','en','1','2007-10-18 04:28:24','1',NULL,'11206FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11207','136557','A condition due to congenital lack of thyroid hormone, marked by arrested physical and mental development, dystrophy of the bones and soft parts, and lowered basal metabolism. It is the congenital form of thyroid deficiency, while MYXEDEMA is the acquired form. (From Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'11207FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
