REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11312','137131','Disturbances in sexual desire and the psychophysiologic changes that characterize the sexual response cycle and cause marked distress and interpersonal difficulty. (APA, DSM-IV, 1994)','en','1','2007-10-18 04:28:24','1',NULL,'11312FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11313','137132','A group of inherited diseases that share similar phenotypes but are genetically diverse. Different genetic loci for autosomal recessive, autosomal dominant, and x-linked forms of hereditary spastic paraplegia have been identified. Clinically, patients present with slowly progessive distal limb weakness and lower extremity spasticity. Peripheral sensory neurons may be affected in the later stages of the disease. (J Neurol Neurosurg Psychiatry 1998 Jan;64(1):61-6; Curr Opin Neurol 1997 Aug;10(4):313-8)','en','1','2007-10-18 04:28:24','1',NULL,'11313FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11314','137138','Inborn errors of bilirubin metabolism resulting in excessive amounts of bilirubin in the circulating blood, either because of increased bilirubin production or because of delayed clearance of bilirubin from the blood.','en','1','2007-10-18 04:28:24','1',NULL,'11314FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
