REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11321','137151','The misuse of phencyclidine with associated psychological symptoms and impairment in social or occupational functioning.','en','1','2007-10-18 04:28:24','1',NULL,'11321FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11322','137159','Excessive lateral nail growth into the nail fold. Because the lateral margin of the nail acts as a foreign body, inflammation and granulation may result. It is caused by improperly fitting shoes and by improper trimming of the nail.','en','1','2007-10-18 04:28:24','1',NULL,'11322FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11323','137160','Stenosis of the conus arteriosus (infundibulum) with or without involvement of the pulmonary valve. It is usually associated with a defect in the interventricular septum.','en','1','2007-10-18 04:28:24','1',NULL,'11323FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
