REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11325','137166','An acute viral infection involving the respiratory tract. It is marked by inflammation of the nasal mucosa, the pharynx, and conjunctiva, and by headache and severe, often generalized, myalgia.','en','1','2007-10-18 04:28:24','1',NULL,'11325FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
