REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11327','137179','A chronic neoplasm-like inflammatory reaction, usually affecting the orbital tissues of both eyes, also known as orbital myositis.','en','1','2007-10-18 04:28:24','1',NULL,'11327FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11330','137193','Inflammatory disease of the breast, or mammary gland.','en','1','2007-10-18 04:28:24','1',NULL,'11330FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11331','137195','Inflammation of the oral mucosa, due to local or systemic factors, which may involve the buccal and labial mucosa, palate, tongue, floor of the mouth, and the gingivae. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'11331FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
