REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11767','138313','A regressive change of teeth characterized by excessive development of secondary cementum on the tooth surface. It may occur on any part of the root, but the apical two-thirds are most commonly affected. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'11767FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
