REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11778','138327','Metabolic disorders affecting amino acid metabolism. They are present at birth, although they may not become symptomatic until later in life. The majority of these disorders are inherited and present in the neonatal period with metabolic disturbances (e.g., ACIDOSIS) and neurologic manifestations.','en','1','2007-10-18 04:28:24','1',NULL,'11778FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
