REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11964','138686','Stomatitis caused by Herpesvirus hominis. It usually occurs as acute herpetic stomatitis (or gingivostomatitis), an oral manifestation of primary herpes simplex seen primarily in children and adolescents.','en','1','2007-10-18 04:28:24','1',NULL,'11964FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
