REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('11982','138707','A skin and mucous membrane disease characterized by an eruption of macules, papules, nodules, vesicles, and/or bullae with characteristic \"bull\'s-eye\" lesions usually occurring on the dorsal aspect of the hands and forearms.','en','1','2007-10-18 04:28:24','1',NULL,'11982FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
