REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12245','139345','Any of several developmental anomalies involving the total or partial failure of the indifferent embryonic gonad to differentiate into ovary or testis. This concept includes gonadal agenesis.','en','1','2007-10-18 04:28:24','1',NULL,'12245FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12246','139346','A genetic skin disease characterized by hypoplasia of the dermis, herniations of fat, and hand anomalies. It is found exclusively in females and transmitted as an X-linked dominant trait.','en','1','2007-10-18 04:28:24','1',NULL,'12246FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
