REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12250','139355','The presence of glucose in the urine, especially the excretion of an abnormally large amount of sugar (glucose) in the urine. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'12250FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12251','139358','A group of inherited metabolic disorders involving the enzymes responsible for the synthesis and degradation of glycogen. In some patients, prominent liver involvement is presented. In others, more generalized storage of glycogen occurs, sometimes with prominent cardiac involvement.','en','1','2007-10-18 04:28:24','1',NULL,'12251FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
