REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12571','140330','A disorder occurring in children born to alcoholic women who continue to drink heavily during pregnancy. Common abnormalities are growth deficiency (prenatal and postnatal), altered morphogenesis, mental deficiency, and characteristic facies - small eyes and flattened nasal bridge. Fine motor dysfunction and tremulousness are observed in the newborn.','en','1','2007-10-18 04:28:24','1',NULL,'12571FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12572','140348','A disorder occurring in children born to alcoholic women who continue to drink heavily during pregnancy. Common abnormalities are growth deficiency (prenatal and postnatal), altered morphogenesis, mental deficiency, and characteristic facies - small eyes and flattened nasal bridge. Fine motor dysfunction and tremulousness are observed in the newborn.','en','1','2007-10-18 04:28:24','1',NULL,'12572FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12573','140352','Disorder characterized by recurrent, intense sexually arousing fantasies, sexual urges, or behaviors involving cross-dressing in a heterosexual male. The fantasies, urges, or behaviors cause clinically significant distress or impairment in social, occupational or other areas of functioning. (from APA, DSM-IV, 1994)','en','1','2007-10-18 04:28:24','1',NULL,'12573FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
