REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12578','140411','A disorder occurring in children born to alcoholic women who continue to drink heavily during pregnancy. Common abnormalities are growth deficiency (prenatal and postnatal), altered morphogenesis, mental deficiency, and characteristic facies - small eyes and flattened nasal bridge. Fine motor dysfunction and tremulousness are observed in the newborn.','en','1','2007-10-18 04:28:24','1',NULL,'12578FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12579','140413','Gait abnormalities that are a manifestation of nervous system dysfunction. These conditions may be caused by a wide variety of disorders which affect motor control, sensory feedback, and muscle strength including: CENTRAL NERVOUS SYSTEM DISEASES; PERIPHER','en','1','2007-10-18 04:28:24','1',NULL,'12579FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
