REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12581','140430','The involuntary discharge of urine as a result of anatomic displacement which exerts an opening pull on the bladder orifice. It often occurs during coughing or other forceful stresses. (From Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'12581FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
