REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12584','140440','Absence of hair from areas where it is normally present.','en','1','2007-10-18 04:28:24','1',NULL,'12584FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
