REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12586','140462','Excess hair in females and children with an adult male pattern of distribution. The concept does not include HYPERTRICHOSIS, which is localized or generalized excess hair.','en','1','2007-10-18 04:28:24','1',NULL,'12586FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
