REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12656','140613','Combination of pulmonary valve stenosis and atrial septal defect with right ventricular hypertrophy.','en','1','2007-10-18 04:28:24','1',NULL,'12656FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12657','140722','Failure of the uterus to contract with normal strength and duration and at normal intervals during labor. It is also called uterine atony.','en','1','2007-10-18 04:28:24','1',NULL,'12657FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
