REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12869','141349','A general term for a group of inherited disorders which are characterized by progressive degeneration of skeletal muscles (MUSCLE, SKELETAL).','en','1','2007-10-18 04:28:24','1',NULL,'12869FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
