REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('12888','141422','A group of inherited disorders of the connective tissue that vary in severity and are transmitted as autosomal recessive, autosomal dominant, or X-linked recessive traits. The primary characteristics are hyperextensible skin and joints, tendency to bruise, reduced wound healing capability, pseudotumors, and ocular defects. (From Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'12888FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
