REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13126','142165','Harm or hurt to the ankle or ankle joint usually inflicted by an external source.','en','1','2007-10-18 04:28:24','1','2013-02-01 15:14:18','13126FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13128','142174','A definite pathologic process with a characteristic set of signs and symptoms. It may affect the whole body or any of its parts, and its etiology, pathology, and prognosis may be known or unknown.','en','1','2007-10-18 04:28:24','1',NULL,'13128FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
