REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13183','142388','Infection with flukes of the genus Dicrocoelium.','en','1','2007-10-18 04:28:24','1',NULL,'13183FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13184','142399','Pneumoconiosis due to the inhalation of dust of stone, sand, or flint containing silicon dioxide, with formation of generalized, nodular fibrotic changes in both lungs. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'13184FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13185','142402','Persistently high arterial blood pressure. Currently accepted threshold levels are 140 mm Hg systolic and 90 mm Hg diastolic pressure.','en','1','2007-10-18 04:28:24','1',NULL,'13185FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13186','142403','Congenital malformations of the central nervous system and adjacent structures related to defective neural tube closure during the first trimester of pregnancy generally occurring between days 18-29 of gestation. Ectodermal and mesodermal malformations (mainly involving the skull and vertebrae) may occur as a result of defects of neural tube closure. (From Joynt, Clinical Neurology, 1992, Ch55, pp31-41)','en','1','2007-10-18 04:28:24','1',NULL,'13186FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
