REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13193','142420','Protrusion of some part of the abdominal or retroperitoneal structures through the diaphragm into the thorax. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'13193FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13194','142421','Elevation of the dome of the diaphragm, usually the result of paralysis of a phrenic nerve. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'13194FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13195','142423','A type of irritant dermatitis localized to the area in contact with a diaper and occurring most often as a reaction to prolonged contact with urine, feces, or retained soap or detergent.','en','1','2007-10-18 04:28:24','1',NULL,'13195FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
