REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13212','142451','Ulcers of the foot as a complication of diabetes. Diabetic foot, often with infection, is a common serious complication of diabetes and may require hospitalization and disfiguring surgery. The foot ulcers are probably secondary to neuropathies and vascular problems.','en','1','2007-10-18 04:28:24','1',NULL,'13212FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
