REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13221','142463','Complication of diabetes resulting from severe insulin deficiency coupled with an absolute or relative increase in glucagon concentration. The metabolic acidosis is caused by the breakdown of adipose stores and resulting increased levels of free fatty acids. Glucagon accelerates the oxidation of the free fatty acids producing excess ketone bodies (ketosis).','en','1','2007-10-18 04:28:24','1',NULL,'13221FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
