REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13228','142474','Diabetes mellitus characterized by insulin deficiency, sudden onset, severe hyperglycemia, rapid progression to ketoacidosis, and death unless treated with insulin. The disease may occur at any age, but is most common in childhood or adolescence.','en','1','2007-10-18 04:28:24','1','2013-01-26 14:16:44','13228FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13229','142478','Either symptomatic diabetes or impaired glucose tolerance induced by pregnancy but resolved at the end of pregnancy. It does not include previously diagnosed diabetics who become pregnant (PREGNANCY IN DIABETES).','en','1','2007-10-18 04:28:24','1',NULL,'13229FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
