REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13265','142563','An affective disorder manifested by either a dysphoric mood or loss of interest or pleasure in usual activities. The mood disturbance is prominent and relatively persistent.','en','1','2007-10-18 04:28:24','1',NULL,'13265FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
