REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13484','143346','New blood vessels originating from the corneal veins and extending from the limbus into the adjacent corneal stroma. These vessels may lie in the superficial and/or deep corneal stroma. Neovascularization is a sequel to numerous inflammatory diseases of the ocular anterior segment, including trachoma, viral interstitial keratitis, microbial keratoconjunctivitis, and the immune response elicited by corneal transplantation.','en','1','2007-10-18 04:28:24','1',NULL,'13484FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
