REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13524','143480','A fibromatosis of the palmar fascia characterized by thickening and contracture of the fibrous bands on the palmar surfaces of the hand and fingers. It arises most commonly in men between the ages of 30 and 50.','en','1','2007-10-18 04:28:24','1',NULL,'13524FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13525','143487','Permanent fixation of the hip in primary positions, with limited passive or active motion at the hip joint. Locomotion is difficult and pain is sometimes present when the hip is in motion. It may be caused by trauma, infection, or poliomyelitis. (From Current Medical Information & Technology, 5th ed)','en','1','2007-10-18 04:28:24','1',NULL,'13525FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
