REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('13989','145228','A slowly progressive condition of unknown etiology, characterized by deposition of fibrous tissue in the retroperitoneal space compressing the ureters, great vessels, bile duct, and other structures. When associated with abdominal aortic aneurysm, it may be called chronic periaortitis or inflammatory perianeurysmal fibrosis.','en','1','2007-10-18 04:28:24','1',NULL,'13989FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
