REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14054','145386','Ulcer that occurs in those portions of the alimentary tract which come into contact with gastric juice containing pepsin and acid. It occurs when the amount of acid and pepsin is sufficient to overcome the gastric mucosal barrier.','en','1','2007-10-18 04:28:24','1',NULL,'14054FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
