REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14131','145620','An acute diarrheal disease endemic in India and Southeast Asia whose causative agent is VIBRIO CHOLERAE. This condition can lead to severe dehydration in a matter of hours unless quickly treated.','en','1','2007-10-18 04:28:24','1','2011-12-22 18:54:38','14131FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
