REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14136','145634','A malignant tumor arising from the intrahepatic bile duct epithelium. It is composed of ducts lined by cuboidal or columnar cells that do not contain bile, with abundant stroma. (From Holland et al., Cancer Medicine, 3d ed, p1455;  Stedman, 25th ed)','en','1','2007-10-18 04:28:24','1',NULL,'14136FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
