REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14312','146062','A disease characterized by intestinal malabsorption and precipitated by gluten-containing foods. The intestinal mucosa shows loss of villous structure.','en','1','2007-10-18 04:28:24','1',NULL,'14312FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14313','146063','Diseases of the parasympathetic or sympathetic divisions of the AUTONOMIC NERVOUS SYSTEM; which has components located in the CENTRAL NERVOUS SYSTEM and PERIPHERAL NERVOUS SYSTEM. Autonomic dysfunction may be associated with HYPOTHALAMIC DISEASES; BRAIN STEM disorders; SPINAL CORD DISEASES; and PERIPHERAL NERVOUS SYSTEM DISEASES. Manifestations include impairments of vegetative functions including the maintenance of BLOOD PRESSURE; HEART RATE; pupil function; SWEATING; REPRODUCTIVE AND URINARY PHYSIOLOGY; and DIGESTION.','en','1','2007-10-18 04:28:24','1',NULL,'14313FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14314','146064','A disease characterized by intestinal malabsorption and precipitated by gluten-containing foods. The intestinal mucosa shows loss of villous structure.','en','1','2007-10-18 04:28:24','1',NULL,'14314FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
