REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14375','146299','A malignancy arising in uterine cervical epithelium and confined thereto, representing a continuum of histological changes ranging from well-differentiated CIN 1 (formerly, mild dysplasia) to severe dysplasia/carcinoma in situ, CIN 3. The lesion arises at the squamocolumnar cell junction at the transformation zone of the endocervical canal, with a variable tendency to develop invasive epidermoid carcinoma, a tendency that is enhanced by concomitant human papillomaviral infection. (Segen, Dictionary of Modern Medicine, 1992)','en','1','2007-10-18 04:28:24','1','2014-12-21 22:19:45','14375FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14376','146336','Tumors or cancer of the prostate.','en','1','2007-10-18 04:28:24','1',NULL,'14376FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
