REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14380','146413','Tumors or cancer of the INTESTINES.','en','1','2007-10-18 04:28:24','1',NULL,'14380FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14381','146417','Cardiac manifestation of MALIGNANT CARCINOID SYNDROME. It is a unique form of fibrosis involving the endocardium, primarily of the right heart. The fibrous deposits tend to cause constriction of the tricuspid and pulmonary valves. (DeVita Jr et al., Cancer: Principles & Practice of Oncology, 3d ed, p1307)','en','1','2007-10-18 04:28:24','1',NULL,'14381FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
