REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14633','147230','The flowing of blood from the marginal gingival area, particularly the sulcus, seen in such conditions as GINGIVITIS, marginal PERIODONTITIS, injury, and ASCORBIC  ACID DEFICIENCY.','en','1','2007-10-18 04:28:24','1',NULL,'14633FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14634','147232','Hemorrhage from vessels in the uterus, sometimes manifested as vaginal bleeding.','en','1','2007-10-18 04:28:24','1','2016-07-10 02:37:15','14634FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14635','147234','Bleeding from the blood vessels of the mouth, which may occur as a result of injuries to the mouth, accidents in oral surgery, or diseases of the gums.','en','1','2007-10-18 04:28:24','1',NULL,'14635FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
