REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14653','147281','Inflammation of the choroid as well as the retina and vitreous body. Some form of visual disturbance is usually present. The most important characteristics of posterior uveitis are vitreous opacities, choroiditis, and chorioretinitis.','en','1','2007-10-18 04:28:24','1',NULL,'14653FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
