REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14679','147370','Pain in the cranial region that may occur as an isolated and benign symptom or as a manifestation of a wide variety of conditions including SUBARACHNOID HEMORRHAGE; CRANIOCEREBRAL TRAUMA; CENTRAL NERVOUS SYSTEM INFECTIONS; INTRACRANIAL HYPERTENSION; and other disorders. In general, recurrent headaches that are not associated with a primary disease process are referred to as HEADACHE DISORDERS (e.g., MIGRAINE).','en','1','2007-10-18 04:28:24','1',NULL,'14679FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14680','147374','Greatly exaggerated width of the mouth, resulting from failure of union of the maxillary and mandibular processes, with extension of the oral orifice toward the ear. The defect may be unilateral or bilateral. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'14680FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14681','147378','Acute inflammation of the walls of the smaller bronchial tubes, with varying amounts of pulmonary consolidation due to spread of the inflammation into peribronchiolar alveoli and the alveolar ducts. (Stedman, 25th ed)','en','1','2007-10-18 04:28:24','1',NULL,'14681FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
