REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14763','147675','Inflammation of the choroid in which the sensory retina becomes edematous and opaque. The inflammatory cells and exudate may burst through the sensory retina to cloud the vitreous body.','en','1','2007-10-18 04:28:24','1',NULL,'14763FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
