REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14772','147721','A benign myxoma of cutaneous nerve sheath origin. Theke is from the Greek theke, sheath. (From Stedman, 25th ed)','en','1','2007-10-18 04:28:24','1',NULL,'14772FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14774','147723','Unusual tumor affecting any site of the body, but most often encountered in the head and neck. Considerable debate has surrounded the histogenesis of this neoplasm; however, it is considered to be a myoblastoma of, usually, a benign nature. It affects women more often than men. When it develops beneath the epidermis or mucous membrane, it can lead to proliferation of the squamous cells and mimic squamous cell carcinoma.','en','1','2007-10-18 04:28:24','1',NULL,'14774FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14775','147731','A benign tumor composed of fat cells.','en','1','2007-10-18 04:28:24','1',NULL,'14775FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14787','147747','A benign tumor characterized histologically by tall columnar epithelium within a lymphoid tissue stroma. It is usually found in the salivary glands, especially the parotid.','en','1','2007-10-18 04:28:24','1',NULL,'14787FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14788','147748','Tumors or cancer of the SALIVARY GLANDS.','en','1','2007-10-18 04:28:24','1',NULL,'14788FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14789','147750','Diseases of lymph or lymph vessels.','en','1','2007-10-18 04:28:24','1',NULL,'14789FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
