REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14893','148068','A variety of TUBERCULOSIS affecting various birds, including chickens and ducks. It is caused by MYCOBACTERIUM AVIUM and characterized by tubercles consisting principally of epithelioid cells.','en','1','2007-10-18 04:28:24','1',NULL,'14893FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('14894','148071','Aseptic or avascular necrosis of the femoral head. The major types are idiopathic (primary), as a complication of fractures or dislocations, and LEGG-PERTHES DISEASE.','en','1','2007-10-18 04:28:24','1',NULL,'14894FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
