REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15088','148652','A painful linear ulcer at the margin of the anus. It appears as a crack or slit in the mucous membrane of the anus and is very painful and difficult to heal. (Dorland, 27th ed & Stedman, 25th ed)','en','1','2007-10-18 04:28:24','1','2015-07-17 21:15:44','15088FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
