REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15213','148999','Dysentery resulting from ulcerative inflammation of the bowel, caused chiefly by infection with ENTAMOEBA HISTOLYTICA. This condition may be associated with amebic infection of the liver and other distant sites.','en','1','2007-10-18 04:28:24','1',NULL,'15213FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
