REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15391','149603','An acute, diffuse, and suppurative inflammation of loose connective tissue, particularly the deep subcutaneous tissues, and sometimes muscle, which is most commonly seen as a result of infection of a wound, ulcer, or other skin lesions.','en','1','2007-10-18 04:28:24','1',NULL,'15391FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15393','149606','Replacement of the bone marrow by fibrous tissue, occurring in association with a myeloproliferative disorder or secondary to another, unrelated condition. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'15393FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
