REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15413','149665','Nonlymphocytic leukemia in which 20-30% of the bone marrow or peripheral blood cells are of megakaryocyte lineage. Myelofibrosis or increased bone marrow reticulin is common.','en','1','2007-10-18 04:28:24','1',NULL,'15413FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
