REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15491','149856','DEF: Frequent and loose bowel movements of acute onset (< 24 hours).  DESC: Commonly associated with abdominal pain. May be associated with blood or mucus in the stool. REF: <a href=\"http://www.healthatoz.com/healthatoz/Atoz/common/standard/transform.jsp?requestURI=/healthatoz/Atoz/ency/diarrhea.jsp\"> URL</a>','en','1','2007-10-18 04:28:24','1','2014-12-09 14:52:18','15491FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
