REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15553','150021','A rare congenital and familial form of diabetes insipidus, resulting from failure of the renal tubules to absorb water. There is excessive production of antidiuretic hormones but the tubules fail to respond to it. (Dorland, 27th ed)','en','1','2007-10-18 04:28:24','1',NULL,'15553FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
