REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15612','150487','A transient and intermittent type of arrhythmia with episodes lasting from a few seconds to a minute which usually occurs in patients with acute myocardial infarction or with digitalis toxicity. Suppressive therapy is rarely necessary because the ventricular rate is generally less than 100 beats per minute.','en','1','2007-10-18 04:28:24','1',NULL,'15612FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15613','150489','Conditions characterized by activation of the whole or some part of the ventricle by the atrial impulse earlier than would be expected if the impulse reached the ventricle by way of the normal specific conduction system only.','en','1','2007-10-18 04:28:24','1',NULL,'15613FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15614','150492','Infestations with arthropods of the order Acarina other than the suborder Ixodides.','en','1','2007-10-18 04:28:24','1',NULL,'15614FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15616','150497','The presence of abnormally low levels of lipoproteins in the serum.','en','1','2007-10-18 04:28:24','1',NULL,'15616FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15617','150499','A genus of parasitic nematodes whose organisms are distributed in Central and South America. Characteristics include a smooth cuticle and an enlarged anterior end.','en','1','2007-10-18 04:28:24','1',NULL,'15617FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
