REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('15745','150948','An infantile syndrome characterized by a cat-like cry, failure to thrive, microcephaly, MENTAL RETARDATION, spastic quadriparesis, micro- and retrognathia, glossoptosis, bilateral epicanthus, hypertelorism, and tiny external genitalia. It is caused by a deletion of the short arm of chromosome 5 (5p-).','en','1','2007-10-18 04:28:24','1',NULL,'15745FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
