REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('17596','163090','গর্ভাবস্থায় মা এবং/অথবা গর্ভস্থ শিশু স্বাভাবিকের চেয়ে বেশি স্বাস্থ্য /মৃত্যুঝুঁকিতে আছে, কারন মায়ের আর্থসামাজিক দুরাবস্থা যেমন দুঃস্থ উন্নয়ন দলের সদস্য, নিম্ন মাতৃ শিক্ষার হার,খানায় খাদ্যনিরাপত্তা্র অভাব ও হতদরিদ্র পয়ঃনিষ্কাশন ব্যবস্থা । যা গর্ভকালীন উচ্চ ঝুঁকির তালিকায় সংযুক্ত হতে পারে ।','bn','1','2015-12-18 03:29:54','1',NULL,'17596FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
