REPLACE INTO `concept_description` (`concept_description_id`, `concept_id`, `description`, `locale`, `creator`, `date_created`, `changed_by`, `date_changed`, `uuid`) values('17653','163257','The Didinga language (’Di’dinga) is an Eastern Sudanic language spoken by the Chukudum and Lowudo peoples of the Didinga Hills of South Sudan. It is classified as a member of the southwest branch Surmic languages (Fleming 1983). Its nearest relative is Narim.\r\nREF: https://en.wikipedia.org/wiki/Didinga_language','en','1','2016-02-16 22:12:06','1','2016-02-16 22:12:14','17653FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF');
